def move_course_names_to_catalog(apps, schema_editor):
    Course = apps.get_model("students", "Course")
    Student = apps.get_model("students", "Student")
    database = schema_editor.connection.alias

    for student in Student.objects.using(database).all().iterator():
        name = student.course.strip() or "Unassigned"
        course = Course.objects.using(database).filter(name=name).first()
        if course is None:
            base_code = slugify(name).replace("-", "").upper()[:20] or "COURSE"
            code = base_code
            suffix = 1
            while Course.objects.using(database).filter(code=code).exists():
                suffix_text = str(suffix)
                code = f"{base_code[:20 - len(suffix_text)]}{suffix_text}"
                suffix += 1
            course = Course.objects.using(database).create(code=code, name=name)
        student.course_record_id = course.pk
        student.save(update_fields=["course_record"], using=database)


def restore_course_names(apps, schema_editor):
    Student = apps.get_model("students", "Student")
    database = schema_editor.connection.alias
    for student in Student.objects.using(database).all().iterator():
        if student.course_record_id:
            student.course = student.course_record.name
            student.save(update_fields=["course"], using=database)


